def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v, _ in counts.most_common() if v != bg)

    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    if not points:
        return [row[:] for row in grid]

    top = min(r for r, c in points)
    bottom = max(r for r, c in points)

    col_counts = [sum(grid[r][c] == fg for r in range(h)) for c in range(w)]
    rails = sorted(range(w), key=lambda c: col_counts[c], reverse=True)[:2]
    left, right = sorted(rails)

    out = [row[:] for row in grid]

    # Complete the two vertical rails between the top and bottom edges.
    for r in range(top, bottom + 1):
        for c in (left, right):
            if out[r][c] == bg:
                out[r][c] = 2

    # Complete the horizontal edges across the rails.
    for r in (top, bottom):
        for c in range(left, right + 1):
            if out[r][c] == bg:
                out[r][c] = 2

    return out
